INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q3', 'Câu 03: Thế nào là triều hỗn hợp?', 'gk2_kttv', 3);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q3_a1', 'Là hiện tượng trong nửa tháng âm lịch, chu kỳ thuỷ triều thay đổi từ bán nhật triều sang nhật triều', 'gk2_kttv_q3');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q3_a2', 'Là hiện tượng trong nửa tháng âm lịch, chu kỳ thuỷ triều thay đổi từ nhật triều sang bán nhật triều', 'gk2_kttv_q3');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q3_a3', 'Là hiện tượng trong nửa tháng âm lịch, chu kỳ thuỷ triều thay đổi từ bán nhật triều sang nhật triều và ngược lại.', 'gk2_kttv_q3');
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q3_a4', 'Là hiện tượng trong nửa tháng âm lịch, chu kỳ thuỷ triều không thay đổi từ nhật triều sang bán nhật triều', 'gk2_kttv_q3');
INSERT INTO questions (id, text, subject_id, display_order) VALUES ('gk2_kttv_q4', 'Câu 04: Ở chu kỳ bán nhật triều thì triều hỗn hợp được gọi là?', 'gk2_kttv', 4);
INSERT INTO answers (id, text, question_id) VALUES ('gk2_kttv_q4_a1', 'Bán nhật triều đều', 'gk2_kttv_q4');
